"""tabula.engine -- the table model, the transforms, the output formats and the command line.

This is the one module every command lives in. A command is a function `cmd_NAME(args, opts)` that gets the
positional arguments (a list of strings) and the options (a dict) and returns a Table, which `main` then prints in the
format asked for (`--format text|csv|json`, text by default). A mistake in a file or in a request raises TabulaError
(exit status 1); a command line that is not shaped right raises UsageError (exit status 2).
"""
import csv
import io
import json
import re
import sys
import unicodedata
from decimal import (Decimal, InvalidOperation, ROUND_HALF_UP, ROUND_FLOOR, ROUND_CEILING, ROUND_DOWN, getcontext,
                     localcontext)

from .errors import TabulaError, UsageError

PROG = "tabula"
FORMATS = ("text", "csv", "json")
# Every choice option: name -> (allowed values, default). `parse_args` reads them all from this one table, so every
# command line accepts all of them, and `opts` always holds each one.
OPTIONS = {"format": (FORMATS, "text"), "kind": (("inner", "left"), "inner"), "keep": (("first", "last"), "first")}
getcontext().prec = 60

NUMBER = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)")


# --- numbers -------------------------------------------------------------------------------------------------

def to_decimal(text):
    """The Decimal a cell holds, or None when it is not a plain decimal number (no exponent, no thousands marks)."""
    text = text.strip()
    if not NUMBER.fullmatch(text):
        return None
    try:
        return Decimal(text)
    except InvalidOperation:
        return None


def fmt_decimal(number):
    """A Decimal as plain text: no exponent, no negative zero."""
    text = format(number, "f")
    if text.startswith("-") and not text.strip("-0."):
        text = text[1:]
    return text


def _need_number(value):
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%r is not a number" % value)
    return number


def fmt_round2(number):
    """A Decimal rounded half up to two decimals, always printed with two (`-0.001` is `0.00`)."""
    with localcontext() as ctx:
        ctx.prec = max(ctx.prec, number.adjusted() + 4)
        return fmt_decimal(number.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def compare_values(left, right):
    """-1, 0 or 1: as numbers when both texts are numbers, else as text by code point."""
    a, b = to_decimal(left), to_decimal(right)
    if a is None or b is None:
        a, b = left, right
    return (a > b) - (a < b)


def _row_error(source, number, message):
    """The TabulaError for a mistake in data row NUMBER (counted from 1, header not counted) of a file."""
    return TabulaError("%s: row %d: %s" % (source, number, message))


def _cell_number(source, number, column, value):
    """The Decimal in a cell, or `FILE: row N: column 'C': 'x' is not a number`."""
    try:
        return _need_number(value)
    except TabulaError as exc:
        raise _row_error(source, number, "column %r: %s" % (column, exc))


def _need_count(arg, name):
    if arg is None or not arg.isdigit():
        raise TabulaError("%s needs a whole number argument, got %r" % (name, arg))
    return int(arg)


def _need_decimal_arg(arg, name):
    number = None if arg is None else to_decimal(arg)
    if number is None:
        raise TabulaError("%s needs a number argument, got %r" % (name, arg))
    return number


def _no_arg(name, arg):
    if arg is not None:
        raise TabulaError("%s takes no argument, got %r" % (name, arg))


def _need_text(arg, name):
    if arg is None:
        raise TabulaError("%s needs an argument" % name)
    return arg


# --- the table -----------------------------------------------------------------------------------------------

class Table:
    """Column names and rows of strings. `source` names where it came from, for messages."""

    def __init__(self, columns, rows, source="<table>"):
        self.columns = list(columns)
        self.rows = [list(r) for r in rows]
        self.source = source

    def __len__(self):
        return len(self.rows)

    def index(self, name):
        """Position of a column; TabulaError when there is none."""
        try:
            return self.columns.index(name)
        except ValueError:
            raise TabulaError("%s: no column %r (columns: %s)" % (self.source, name, ", ".join(self.columns)))

    def column(self, name):
        at = self.index(name)
        return [row[at] for row in self.rows]

    def dicts(self):
        return [dict(zip(self.columns, row)) for row in self.rows]

    def with_rows(self, rows, columns=None):
        return Table(self.columns if columns is None else columns, rows, self.source)


def parse_text(text, source):
    """CSV text into a Table. Blank lines are ignored; every row must have as many fields as the header."""
    if text.startswith("﻿"):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=""))
    columns, rows = None, []
    try:
        for fields in reader:
            if not fields:
                continue
            if columns is None:
                for name in fields:
                    if not name.strip():
                        raise TabulaError("%s: line %d: empty column name" % (source, reader.line_num))
                if len(set(fields)) != len(fields):
                    raise TabulaError("%s: line %d: duplicate column name" % (source, reader.line_num))
                columns = fields
                continue
            if len(fields) != len(columns):
                raise TabulaError("%s: line %d: expected %d fields, found %d"
                                  % (source, reader.line_num, len(columns), len(fields)))
            rows.append(fields)
    except csv.Error as exc:
        raise TabulaError("%s: line %d: %s" % (source, reader.line_num, exc))
    if columns is None:
        raise TabulaError("%s: no header line" % source)
    return Table(columns, rows, source)


def load(path):
    """Read a CSV file (UTF-8, optional byte order mark, LF or CRLF) into a Table."""
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except OSError as exc:
        raise TabulaError("%s: cannot read: %s" % (path, exc.strerror or exc))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise TabulaError("%s: not valid UTF-8" % path)
    return parse_text(text, path)


# --- output --------------------------------------------------------------------------------------------------

def render_text(table):
    cells = [table.columns] + table.rows
    widths = [max(len(row[i]) for row in cells) for i in range(len(table.columns))]
    lines = ["  ".join(cell.ljust(width) for cell, width in zip(row, widths)).rstrip() for row in cells]
    return "\n".join(lines) + "\n"


def render_csv(table):
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(table.columns)
    writer.writerows(table.rows)
    return out.getvalue()


def render_json(table):
    return json.dumps(table.dicts(), ensure_ascii=False) + "\n"


RENDERERS = {"text": render_text, "csv": render_csv, "json": render_json}


def render(table, fmt="text"):
    return RENDERERS[fmt](table)



def parse_spec(spec):
    """`name` or `name:arg` into (function, arg); the argument is everything after the first colon."""
    name, _, arg = spec.partition(":")
    if name not in TRANSFORMS:
        raise TabulaError("unknown transform %r" % name)
    return TRANSFORMS[name], (arg if ":" in spec else None)


def apply_transforms(value, specs):
    for fn, arg in specs:
        value = fn(value, arg)
    return value


# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage, at_least=False):
    if len(args) < count if at_least else len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    _need_args(args, 3, "apply FILE COLUMN TRANSFORM...", at_least=True)
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise _row_error(table.source, number, exc)
        rows.append(row)
    return table.with_rows(rows)


SORT_MODIFIERS = ("num", "desc")


def _parse_sort_key(arg):
    """(column, numeric, descending) from a KEY `COLUMN[:num][:desc]`."""
    column, *mods = arg.split(":")
    if not column:
        raise UsageError("sort: empty column in key %r" % arg)
    for mod in mods:
        if mod not in SORT_MODIFIERS:
            raise UsageError("sort: unknown modifier %r in key %r (use %s)" % (mod, arg, " or ".join(SORT_MODIFIERS)))
    if len(set(mods)) != len(mods):
        raise UsageError("sort: modifier given twice in key %r" % arg)
    return column, "num" in mods, "desc" in mods


def cmd_sort(args, opts):
    _need_args(args, 2, "sort FILE KEY...", at_least=True)
    keys = [_parse_sort_key(arg) for arg in args[1:]]
    table = load(args[0])
    sort_keys = []
    for column, numeric, descending in keys:
        at = table.index(column)
        if numeric:
            values = [_cell_number(table.source, n, column, row[at]) for n, row in enumerate(table.rows, 1)]
        else:
            values = [row[at] for row in table.rows]
        sort_keys.append((values, descending))
    order = list(range(len(table.rows)))
    for values, descending in reversed(sort_keys):
        order.sort(key=values.__getitem__, reverse=descending)
    return table.with_rows([table.rows[i] for i in order])


FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")


def _parse_condition(arg):
    """(column, operator, value) from `COLUMN OP VALUE`: the operator starting earliest wins, the longer one on a tie."""
    best = None
    for op in FILTER_OPERATORS:
        at = arg.find(op)
        if at >= 0 and (best is None or at < best[0] or (at == best[0] and len(op) > len(best[1]))):
            best = (at, op)
    if best is None:
        raise UsageError("filter: no operator in condition %r (use %s)" % (arg, " ".join(FILTER_OPERATORS)))
    at, op = best
    if at == 0:
        raise UsageError("filter: no column in condition %r" % arg)
    return arg[:at], op, arg[at + len(op):]


def _condition_test(op, value):
    """A function from a cell to True/False for OP and VALUE."""
    if op == "~":
        needle = value.lower()
        return lambda cell: needle in cell.lower()
    wanted = {"==": (0,), "!=": (-1, 1), ">=": (0, 1), "<=": (-1, 0), ">": (1,), "<": (-1,)}[op]
    return lambda cell: compare_values(cell, value) in wanted


def cmd_filter(args, opts):
    _need_args(args, 2, "filter FILE CONDITION...", at_least=True)
    conditions = [_parse_condition(arg) for arg in args[1:]]
    table = load(args[0])
    tests = [(table.index(column), _condition_test(op, value)) for column, op, value in conditions]
    return table.with_rows([row for row in table.rows if all(test(row[at]) for at, test in tests)])


GROUP_FUNCTIONS = ("sum", "min", "max", "mean")


def _parse_aggregate(arg):
    """(output column name, function, column or None) from `count` or `FUNC:COLUMN`."""
    if arg == "count":
        return "count", "count", None
    func, colon, column = arg.partition(":")
    if func not in GROUP_FUNCTIONS or not colon or not column:
        raise UsageError("group: bad aggregate %r (use count, sum:C, min:C, max:C or mean:C)" % arg)
    return arg.replace(":", "_"), func, column


def _mean2(total, count):
    """TOTAL / COUNT as text, exact, rounded half up (away from zero) to two decimals."""
    scaled = total * 100
    whole = scaled // count
    if 2 * abs(scaled - whole * count) >= count:
        whole += 1 if scaled >= 0 else -1
    return fmt_round2(whole.scaleb(-2))


def cmd_group(args, opts):
    _need_args(args, 3, "group FILE BY AGGREGATE...", at_least=True)
    aggregates = [_parse_aggregate(arg) for arg in args[2:]]
    if len(set(args[2:])) != len(args[2:]):
        raise UsageError("group: the same aggregate given twice")
    table = load(args[0])
    by = table.index(args[1])
    names = [args[1]] + [name for name, _, _ in aggregates]
    for name in names:
        if names.count(name) > 1:
            raise TabulaError("%s: output column %r would appear twice" % (table.source, name))
    columns = {column: table.index(column) for _, _, column in aggregates if column is not None}
    groups = {}
    with localcontext() as ctx:
        ctx.prec = 60 + sum(len(cell) for row in table.rows for cell in row)    # sums stay exact
        for number, row in enumerate(table.rows, 1):
            values = {c: _cell_number(table.source, number, c, row[at]) for c, at in columns.items()}
            group = groups.setdefault(row[by], {"count": 0, "values": {c: [] for c in columns}})
            group["count"] += 1
            for column, value in values.items():
                group["values"][column].append(value)
        rows = []
        for key, group in groups.items():
            out = [key]
            for _, func, column in aggregates:
                values = group["values"].get(column)
                if func == "count":
                    out.append(str(group["count"]))
                elif func == "sum":
                    out.append(fmt_decimal(sum(values, Decimal(0))))
                elif func == "mean":
                    out.append(_mean2(sum(values, Decimal(0)), group["count"]))
                else:
                    best = values[0]
                    for value in values[1:]:
                        if (value < best) if func == "min" else (value > best):
                            best = value
                    out.append(fmt_decimal(best))
            rows.append(out)
    return Table(names, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    key = args[2]
    lat, rat = left.index(key), right.index(key)
    keep = [i for i in range(len(right.columns)) if i != rat]
    names = [right.columns[i] + "_right" if right.columns[i] in left.columns else right.columns[i] for i in keep]
    columns = left.columns + names
    for name in columns:
        if columns.count(name) > 1:
            raise TabulaError("%s: joined column %r would appear twice" % (right.source, name))
    matches = {}
    for row in right.rows:
        matches.setdefault(row[rat], []).append([row[i] for i in keep])
    rows = []
    for row in left.rows:
        found = matches.get(row[lat])
        if found:
            rows.extend(row + other for other in found)
        elif opts["kind"] == "left":
            rows.append(row + [""] * len(keep))
    return Table(columns, rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    at_row, at_col, at_val = table.index(args[1]), table.index(args[2]), table.index(args[3])
    sums = {}
    heads = {}
    with localcontext() as ctx:
        ctx.prec = 60 + sum(len(cell) for row in table.rows for cell in row)    # sums stay exact
        for number, row in enumerate(table.rows, 1):
            head = row[at_col]
            if not head.strip():
                raise _row_error(table.source, number, "column %r: empty value" % args[2])
            if head == args[1]:
                raise _row_error(table.source, number, "column %r: value %r is also the name of the row column" % (args[2], head))
            value = _cell_number(table.source, number, args[3], row[at_val])
            heads.setdefault(head, None)
            cells = sums.setdefault(row[at_row], {})
            cells[head] = cells.get(head, Decimal(0)) + value
    rows = [[key] + [fmt_decimal(cells[head]) if head in cells else "0" for head in heads] for key, cells in sums.items()]
    return Table([args[1]] + list(heads), rows, table.source)


def cmd_dedupe(args, opts):
    _need_args(args, 2, "dedupe FILE KEY...", at_least=True)
    table = load(args[0])
    spots = [table.index(name) for name in args[1:]]
    chosen = {}
    for number, row in enumerate(table.rows):
        key = tuple(row[i] for i in spots)
        if opts["keep"] == "last" or key not in chosen:
            chosen[key] = number
    return table.with_rows([table.rows[number] for number in sorted(chosen.values())])


def cmd_stats(args, opts):
    _need_args(args, 2, "stats FILE COLUMN...", at_least=True)
    table = load(args[0])
    spots = {name: table.index(name) for name in args[1:]}
    values = {name: [] for name in spots}
    for number, row in enumerate(table.rows, 1):
        for name, at in spots.items():
            if row[at].strip():
                values[name].append(_cell_number(table.source, number, name, row[at]))
    rows = []
    with localcontext() as ctx:
        ctx.prec = 60 + sum(len(cell) for row in table.rows for cell in row)    # sums stay exact
        for name in args[1:]:
            found = values[name]
            if not found:
                rows.append([name, "0", "", "", "", ""])
                continue
            ordered = sorted(found)
            half = len(ordered) // 2
            median = _mean2(ordered[half - 1] + ordered[half], 2) if len(ordered) % 2 == 0 else fmt_round2(ordered[half])
            low, high = found[0], found[0]
            for value in found[1:]:
                low, high = (value if value < low else low), (value if value > high else high)
            rows.append([name, str(len(found)), fmt_decimal(low), fmt_decimal(high),
                         _mean2(sum(found, Decimal(0)), len(found)), median])
    return Table(["column", "count", "min", "max", "mean", "median"], rows, table.source)


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "sort rows by one or more keys"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "keep the rows that meet every condition"),
    "group": (cmd_group, "group FILE BY AGGREGATE...", "one row per BY value, with count/sum/min/max/mean"),
    "join": (cmd_join, "join LEFT RIGHT KEY", "join two files on a key column (--kind inner|left)"),
    "pivot": (cmd_pivot, "pivot FILE ROW COLUMN VALUE", "sum VALUE per ROW and COLUMN value"),
    "dedupe": (cmd_dedupe, "dedupe FILE KEY...", "keep the first or last row of each set with equal KEY values (--keep first|last)"),
    "stats": (cmd_stats, "stats FILE COLUMN...", "count, min, max, mean and median of the numbers in each COLUMN"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    options = " ".join("[--%s %s]" % (name, "|".join(choices)) for name, (choices, _) in OPTIONS.items())
    lines = ["usage: %s %s COMMAND ARGS..." % (PROG, options), "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = {name: default for name, (_, default) in OPTIONS.items()}, [], 0
    while i < len(argv):
        arg = argv[i]
        name = arg[2:].split("=", 1)[0] if arg.startswith("--") else None
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in OPTIONS:
            if "=" in arg:
                value = arg.split("=", 1)[1]
            else:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            choices = OPTIONS[name][0]
            if value not in choices:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(choices), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 0
"""The two kinds of failure a command can end in."""


class TabulaError(Exception):
    """A mistake in a file or in what was asked for; the command line ends with exit status 1."""


class UsageError(Exception):
    """A command line that is not shaped right; the command line ends with exit status 2."""
"""tabula: small tools for CSV tables."""
from .engine import Table, load, main, render
from .errors import TabulaError, UsageError

__all__ = ["Table", "TabulaError", "UsageError", "load", "main", "render"]
__version__ = "0.3.0"
import sys

from .engine import main

sys.exit(main())

